mapper.update:
update tb_ai_session


        enable=#{enable}




        and user_id=#{userId}


        and session_id =#{sessionId}

mapper.delete:
update tb_ai_session


             is_del=#{isDel}




        and user_id=#{userId}


        and session_id =#{sessionId}

mapper.select:
select  id, session_id, session_title, user_id,
        enable, feedback, is_del, model_id, created_time, last_time
    from tb_ai_session


       and user_id=#{userId}


       and is_del=#{isDel}


order by last_time desc;
